<?php

declare(strict_types=1);

namespace EventMenu\Services;

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use PDO;
use RuntimeException;

final class TicketService
{
    public function reservePublic(int $eventId,int $batchId,int $quantity,array $buyer,?string $couponCode=null,?string $promoterCode=null):array
    {
        $quantity=max(1,min(10,$quantity));return Database::transaction(function(PDO$pdo)use($eventId,$batchId,$quantity,$buyer,$couponCode,$promoterCode){$stmt=$pdo->prepare('SELECT e.*,t.status tenant_status FROM events e JOIN tenants t ON t.id=e.tenant_id WHERE e.id=? AND e.status="published" FOR UPDATE');$stmt->execute([$eventId]);$event=$stmt->fetch();if(!$event||$event['tenant_status']!=='active')throw new RuntimeException('Evento indisponível.');$stmt=$pdo->prepare('SELECT * FROM ticket_batches WHERE id=? AND event_id=? AND active=1 FOR UPDATE');$stmt->execute([$batchId,$eventId]);$batch=$stmt->fetch();if(!$batch)throw new RuntimeException('Lote indisponível.');$now=new \DateTimeImmutable('now');if($batch['sales_start']&&$now<new \DateTimeImmutable($batch['sales_start']))throw new RuntimeException('Venda deste lote ainda não começou.');if($batch['sales_end']&&$now>new \DateTimeImmutable($batch['sales_end']))throw new RuntimeException('Venda deste lote foi encerrada.');$available=(int)$batch['quantity_total']-(int)$batch['quantity_sold']-(int)$batch['quantity_reserved'];if($available<$quantity)throw new RuntimeException('Quantidade de ingressos indisponível.');$name=trim((string)($buyer['name']??''));$email=mb_strtolower(trim((string)($buyer['email']??'')));$phone=trim((string)($buyer['phone']??''));if($name===''||(!filter_var($email,FILTER_VALIDATE_EMAIL)&&$phone===''))throw new RuntimeException('Informe nome e e-mail ou telefone válido.');$customerId=$this->findOrCreateCustomer($pdo,(int)$event['tenant_id'],$name,$email,$phone);$subtotal=(int)$batch['price_cents']*$quantity;$discount=0;$couponId=null;if($couponCode){$code=strtoupper(trim($couponCode));$c=$pdo->prepare('SELECT * FROM coupons WHERE tenant_id=? AND code=? AND active=1 FOR UPDATE');$c->execute([$event['tenant_id'],$code]);$coupon=$c->fetch();if(!$coupon)throw new RuntimeException('Cupom inválido.');if($coupon['starts_at']&&$now<new \DateTimeImmutable($coupon['starts_at']))throw new RuntimeException('Cupom ainda não está válido.');if($coupon['ends_at']&&$now>new \DateTimeImmutable($coupon['ends_at']))throw new RuntimeException('Cupom expirado.');if($coupon['max_uses']!==null&&((int)$coupon['uses_count']+(int)$coupon['reserved_count'])>=(int)$coupon['max_uses'])throw new RuntimeException('Limite do cupom atingido.');if($subtotal<(int)$coupon['min_order_cents'])throw new RuntimeException('Valor mínimo do cupom não atingido.');$couponId=(int)$coupon['id'];$discount=$coupon['type']==='percent'?(int)round($subtotal*min(100,(int)$coupon['value'])/100):min($subtotal,(int)$coupon['value']);}$promoterId=null;if($promoterCode){$p=$pdo->prepare('SELECT id FROM promoters WHERE tenant_id=? AND code=? AND active=1');$p->execute([$event['tenant_id'],strtoupper(trim($promoterCode))]);$promoterId=$p->fetchColumn()?:null;}$total=max(0,$subtotal-$discount);$publicToken=bin2hex(random_bytes(20));$expires=(new \DateTimeImmutable('+15 minutes'))->format('Y-m-d H:i:s');$stmt=$pdo->prepare('INSERT INTO orders (public_token,tenant_id,unit_id,customer_id,coupon_id,promoter_id,channel,status,payment_status,expires_at,subtotal_cents,discount_cents,total_cents,notes) VALUES (?,?,?,?,?,? ,"event","pending","unpaid",?,?,?,?,?)');$stmt->execute([$publicToken,$event['tenant_id'],$event['unit_id']?:null,$customerId,$couponId,$promoterId,$expires,$subtotal,$discount,$total,'Evento #'.$eventId]);$orderId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO order_items (order_id,product_id,name_snapshot,unit_price_cents,quantity,total_cents) VALUES (?,NULL,?,?,?,?)')->execute([$orderId,'Ingresso '.$event['name'].' — '.$batch['name'],$batch['price_cents'],$quantity,$subtotal]);if($couponId){$pdo->prepare('INSERT INTO coupon_reservations (tenant_id,coupon_id,order_id,discount_cents,status,expires_at) VALUES (?,?,?,?,"reserved",?)')->execute([$event['tenant_id'],$couponId,$orderId,$discount,$expires]);$pdo->prepare('UPDATE coupons SET reserved_count=reserved_count+1 WHERE id=?')->execute([$couponId]);}$tickets=[];for($i=0;$i<$quantity;$i++){$code=$this->newCode($eventId);$qr=bin2hex(random_bytes(32));$s=$pdo->prepare('INSERT INTO tickets (tenant_id,event_id,batch_id,order_id,customer_id,code,status,reserved_until,qr_token) VALUES (?,?,?,?,?,?,"reserved",?,?)');$s->execute([$event['tenant_id'],$eventId,$batchId,$orderId,$customerId,$code,$expires,$qr]);$tickets[]=['id'=>(int)$pdo->lastInsertId(),'code'=>$code,'qr_token'=>$qr];}$pdo->prepare('UPDATE ticket_batches SET quantity_reserved=quantity_reserved+? WHERE id=?')->execute([$quantity,$batchId]);(new NotificationService())->push((int)$event['tenant_id'],'event','Nova reserva de ingressos',$quantity.' ingresso(s) reservados para '.$event['name'],'order',$orderId);return['order_id'=>$orderId,'public_token'=>$publicToken,'total_cents'=>$total,'expires_at'=>$expires,'tickets'=>$tickets];});
    }

    public function transfer(int$ticketId,array$newHolder):array
    {
        Auth::requirePermission('tickets.manage');$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa inválida.');$name=trim((string)($newHolder['name']??''));$email=mb_strtolower(trim((string)($newHolder['email']??'')));$phone=trim((string)($newHolder['phone']??''));if($name===''||(!filter_var($email,FILTER_VALIDATE_EMAIL)&&$phone===''))throw new RuntimeException('Informe nome e e-mail ou telefone do novo titular.');$result=Database::transaction(function(PDO$pdo)use($tenantId,$ticketId,$name,$email,$phone){$s=$pdo->prepare('SELECT t.*,e.name event_name FROM tickets t JOIN events e ON e.id=t.event_id WHERE t.id=? AND t.tenant_id=? LIMIT 1 FOR UPDATE');$s->execute([$ticketId,$tenantId]);$t=$s->fetch();if(!$t)throw new RuntimeException('Ingresso não encontrado.');if($t['status']!=='paid')throw new RuntimeException('Somente ingresso pago e ainda não utilizado pode ser transferido.');if($t['checked_in_at'])throw new RuntimeException('Ingresso já utilizado não pode ser transferido.');$newCustomer=$this->findOrCreateCustomer($pdo,$tenantId,$name,$email,$phone);if((int)$newCustomer===(int)$t['customer_id'])throw new RuntimeException('O novo titular já é o titular atual.');$newQr=bin2hex(random_bytes(32));$newCode=$this->newCode((int)$t['event_id']);$pdo->prepare('UPDATE tickets SET transferred_from_customer_id=customer_id,customer_id=?,code=?,qr_token=?,transferred_at=UTC_TIMESTAMP() WHERE id=?')->execute([$newCustomer,$newCode,$newQr,$ticketId]);Auth::audit('ticket.transferred','ticket',(string)$ticketId,['from_customer_id'=>$t['customer_id'],'to_customer_id'=>$newCustomer]);(new NotificationService())->push($tenantId,'event','Ingresso transferido',$t['event_name'].' · '.$newCode,'ticket',$ticketId);return['ticket_id'=>$ticketId,'event_name'=>$t['event_name'],'code'=>$newCode,'qr_token'=>$newQr,'email'=>$email,'name'=>$name];});$this->queueTicketMail($result);return$result;
    }

    public function queuePaidTicketsForDelivery(?int$tenantId=null,int$limit=100):int
    {
        $pdo=Database::connection();$sql='SELECT t.id,t.code,t.qr_token,e.name event_name,c.name,c.email FROM tickets t JOIN events e ON e.id=t.event_id JOIN customers c ON c.id=t.customer_id WHERE t.status IN ("paid","checked_in") AND c.email IS NOT NULL AND c.email<>""';$args=[];if($tenantId){$sql.=' AND t.tenant_id=?';$args[]=$tenantId;}$sql.=' ORDER BY t.id DESC LIMIT '.max(1,min(500,$limit));$s=$pdo->prepare($sql);$s->execute($args);$n=0;foreach($s->fetchAll()as$t){$this->queueTicketMail($t);$n++;}return$n;
    }

    public function checkIn(string$token):array
    {
        Auth::requirePermission('tickets.manage');$tenantId=Auth::tenantId();if(!$tenantId)throw new RuntimeException('Empresa inválida.');$token=$this->normalizeScannedToken($token);return Database::transaction(function(PDO$pdo)use($tenantId,$token){$s=$pdo->prepare('SELECT * FROM tickets WHERE tenant_id=? AND (qr_token=? OR code=?) LIMIT 1 FOR UPDATE');$s->execute([$tenantId,$token,$token]);$ticket=$s->fetch();if(!$ticket)throw new RuntimeException('Ingresso não encontrado.');if($ticket['status']==='checked_in'){$this->logCheckin($pdo,$tenantId,(int)$ticket['id'],'duplicate');return['ok'=>false,'result'=>'duplicate','ticket'=>$ticket];}if($ticket['status']!=='paid'){$this->logCheckin($pdo,$tenantId,(int)$ticket['id'],'blocked',['status'=>$ticket['status']]);return['ok'=>false,'result'=>'blocked','ticket'=>$ticket];}$pdo->prepare('UPDATE tickets SET status="checked_in",checked_in_at=UTC_TIMESTAMP(),checked_in_by=? WHERE id=?')->execute([Auth::id(),$ticket['id']]);$this->logCheckin($pdo,$tenantId,(int)$ticket['id'],'accepted');return['ok'=>true,'result'=>'accepted','ticket'=>$ticket];});
    }
    public function releaseExpired():int{$result=(new MaintenanceService())->releaseExpiredReservations();return(int)($result['tickets_released']??0);}
    private function findOrCreateCustomer(PDO$pdo,int$tenantId,string$name,string$email,string$phone):int{$id=null;if($email!==''){$s=$pdo->prepare('SELECT id,status FROM customers WHERE tenant_id=? AND email=? LIMIT 1');$s->execute([$tenantId,$email]);$r=$s->fetch();if($r){if(($r['status']??'active')==='blocked')throw new RuntimeException('Titular bloqueado.');$id=$r['id'];}}if(!$id&&$phone!==''){$s=$pdo->prepare('SELECT id,status FROM customers WHERE tenant_id=? AND phone=? LIMIT 1');$s->execute([$tenantId,$phone]);$r=$s->fetch();if($r){if(($r['status']??'active')==='blocked')throw new RuntimeException('Titular bloqueado.');$id=$r['id'];}}if(!$id){$s=$pdo->prepare('INSERT INTO customers (tenant_id,name,phone,email) VALUES (?,?,?,?)');$s->execute([$tenantId,$name,$phone?:null,$email?:null]);return(int)$pdo->lastInsertId();}$pdo->prepare('UPDATE customers SET name=?,phone=COALESCE(NULLIF(?,""),phone),email=COALESCE(NULLIF(?,""),email) WHERE id=?')->execute([$name,$phone,$email,$id]);return(int)$id;}
    private function newCode(int$eventId):string{return sprintf('%s-%s-%s',str_pad((string)$eventId,4,'0',STR_PAD_LEFT),strtoupper(substr(bin2hex(random_bytes(5)),0,10)),strtoupper(substr(bin2hex(random_bytes(2)),0,4)));}
    private function queueTicketMail(array$t):void{if(empty($t['email'])||empty($t['qr_token']))return;$base=rtrim((string)env('APP_URL',''),'/');if($base==='')return;$url=$base.'/ingresso.php?t='.rawurlencode((string)$t['qr_token']);$body="Olá, ".($t['name']??'cliente').".\n\nSeu ingresso para ".($t['event_name']??'o evento')." está disponível.\nCódigo: ".($t['code']??'')."\n\nAbra o ingresso: {$url}\n\nApresente o QR na entrada.";(new MailQueueService())->queue((string)$t['email'],'Seu ingresso · '.($t['event_name']??'EventMenu'),$body,'ticket-delivery|'.($t['id']??$t['ticket_id']??'').'|'.($t['qr_token']??''));}
    private function normalizeScannedToken(string$value):string{$value=trim($value);if(filter_var($value,FILTER_VALIDATE_URL)){$parts=parse_url($value);if(isset($parts['query'])){parse_str($parts['query'],$query);if(!empty($query['t']))return trim((string)$query['t']);}}return$value;}
    private function logCheckin(PDO$pdo,int$tenantId,int$ticketId,string$result,array$metadata=[]):void{$pdo->prepare('INSERT INTO ticket_checkin_logs (tenant_id,ticket_id,user_id,result,metadata) VALUES (?,?,?,?,?)')->execute([$tenantId,$ticketId,Auth::id(),$result,$metadata?json_encode($metadata,JSON_UNESCAPED_UNICODE):null]);}
}
